/** Status-driven building colors. Assets in these subcategories are loaded
 *  on-demand instead of upfront — most orgs only need 1–2 of them at a time. */
export const BUILDING_COLORS = ['blue', 'green', 'red', 'yellow'] as const;
export type BuildingColor = (typeof BUILDING_COLORS)[number];

const BUILDING_COLOR_SET = new Set<string>(BUILDING_COLORS);

/** Assets always needed: tiles, decorations, neutral buildings (incl. scaffolding).
 *  Excludes the colored building variants. */
export function getAlwaysLoadedAssets(): AssetEntry[] {
  return ASSET_CATALOG.filter((a) => !BUILDING_COLOR_SET.has(a.subcategory));
}

export function getAssetsByColor(color: BuildingColor): AssetEntry[] {
  // Only *building* variants are ever color-swapped in the city — statusVisual
  // only ever yields `building_*` ids, and the colored "unit" props (ships,
  // swords, banners, …) aren't placeable through the builder UI. Loading the
  // whole color (buildings + ~28 unit GLTFs) doubled each batch's bytes and
  // parse cost for assets that are never cloned, so restrict to buildings.
  return ASSET_CATALOG.filter((a) => a.category === 'buildings' && a.subcategory === color);
}

/** Extract the color from a building asset id like `building_castle_red`. */
export function extractColor(assetId: string): BuildingColor | null {
  const m = assetId.match(/_(blue|green|red|yellow)$/);
  return (m?.[1] ?? null) as BuildingColor | null;
}

/** The full placeable catalog for a kit (builder palettes, previews). */
export function catalogForKit(kit: Kit): AssetEntry[] {
  return kit === 'space' ? SPACE_ASSET_CATALOG : ASSET_CATALOG;
}
